import{G as r,b as e,c as i,ae as n}from"./chunks/framework.zvXX7P8V.js";const d=JSON.parse('{"title":"GitHub 本周热门 AI 项目","description":"","frontmatter":{"title":"GitHub 本周热门 AI 项目","date":"2026/8/25","author":"花木凋零成兰","tags":["GitHub","AI","周刊","Agent"],"hiddenCover":true},"headers":[],"relativePath":"GitHub相关/GitHub本周热门AI项目.md","filePath":"GitHub相关/GitHub本周热门AI项目.md","lastUpdated":1787614802000}'),o={name:"GitHub相关/GitHub本周热门AI项目.md"};function a(l,t,s,g,u,h){return e(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1787616000000"},[...t[0]||(t[0]=[n('<h1 id="github-本周热门-ai-项目-2026-08-18-2026-08-25" tabindex="-1">GitHub 本周热门 AI 项目（2026-08-18 ~ 2026-08-25） <a class="header-anchor" href="#github-本周热门-ai-项目-2026-08-18-2026-08-25" aria-label="Permalink to &quot;GitHub 本周热门 AI 项目（2026-08-18 ~ 2026-08-25）&quot;">​</a></h1><blockquote><p>数据来源：GitHub Trending 周榜、Trendshift、OSSInsight、whatstrending.ai 及多源交叉验证（采集于 2026-08-18 ~ 08-25）。Star 数为区间末值近似值，周增量为公开快照重建值，适合观察趋势而非精确计数。</p></blockquote><p>本周主线明确：焦点从&quot;模型更强&quot;转向&quot;让 Agent 稳定工作&quot;的工程层——<strong>Skills、编码 Agent、上下文/记忆、AI 安全与内容生成</strong>共同霸榜。</p><h2 id="项目清单" tabindex="-1">项目清单 <a class="header-anchor" href="#项目清单" aria-label="Permalink to &quot;项目清单&quot;">​</a></h2><h3 id="_1-mattpocock-skills" tabindex="-1">1. mattpocock/skills <a class="header-anchor" href="#_1-mattpocock-skills" aria-label="Permalink to &quot;1. mattpocock/skills&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">https://github.com/mattpocock/skills</a></li><li><strong>Star 数</strong>：约 234k（本周新增 ~14,200，居 AI 榜首）</li><li><strong>项目简介</strong>：为编码智能体（Claude Code、Codex 等）提供可组合的工程技能库，覆盖需求澄清、制定计划、代码审查、问题分诊、实现与复盘，强调技能粒度小、可编辑、可跨模型安装。</li><li><strong>本周热度亮点</strong>：上周新增约 14,200 Star 领跑全 AI 榜；继续补充 <code>implement-spec</code> 并调整评审与 grilling 流程，切中企业&quot;复用 Agent 工作方式&quot;的需求，标志 Skills 正成为模型之外的新基础设施。</li><li><strong>技术栈</strong>：TypeScript / JavaScript，Agent Skills 规范，跨模型 CLI 集成。</li></ul><h3 id="_2-harry0703-moneyprinterturbo" tabindex="-1">2. harry0703/MoneyPrinterTurbo <a class="header-anchor" href="#_2-harry0703-moneyprinterturbo" aria-label="Permalink to &quot;2. harry0703/MoneyPrinterTurbo&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/harry0703/MoneyPrinterTurbo" target="_blank" rel="noreferrer">https://github.com/harry0703/MoneyPrinterTurbo</a></li><li><strong>Star 数</strong>：约 115k（本周新增 ~10,700）</li><li><strong>项目简介</strong>：利用 AI 大模型和自动化工作流，根据主题或关键词一键生成高清短视频，整合脚本生成、素材检索、语音合成、字幕、背景音乐与视频剪辑为端到端流水线，支持 API 批量调用。</li><li><strong>本周热度亮点</strong>：本周 fastest riser 之一（多个榜单单周 +10.6k）；v1.3.5 发布，补充 Fish Audio 文档、翻译、容器镜像来源与 SBOM，功能易用性与部署可信度同步提升。</li><li><strong>技术栈</strong>：Python，FFmpeg，大模型 API，自动化工作流。</li></ul><h3 id="_3-openai-codex" tabindex="-1">3. openai/codex <a class="header-anchor" href="#_3-openai-codex" aria-label="Permalink to &quot;3. openai/codex&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">https://github.com/openai/codex</a></li><li><strong>Star 数</strong>：约 115k（本周新增 ~7,900）</li><li><strong>项目简介</strong>：OpenAI 开源的本地终端编码 Agent，可读取仓库、修改代码、执行命令，并参与审查、任务管理与子智能体协作；支持 ChatGPT 计划或 API key，连接 IDE、桌面与云端。</li><li><strong>本周热度亮点</strong>：本周高频 alpha 发布推进 Guardian 审查线程与普通子智能体边界；编码 Agent 竞争重点从&quot;会写代码&quot;转向安全、协作与可靠交付。</li><li><strong>技术栈</strong>：Rust，终端 CLI，OpenAI API，多智能体协作。</li></ul><h3 id="_4-usestrix-strix" tabindex="-1">4. usestrix/strix <a class="header-anchor" href="#_4-usestrix-strix" aria-label="Permalink to &quot;4. usestrix/strix&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/usestrix/strix" target="_blank" rel="noreferrer">https://github.com/usestrix/strix</a></li><li><strong>Star 数</strong>：约 57k（本周新增 ~4,200）</li><li><strong>项目简介</strong>：开源 AI 渗透测试工具，以多个 Agent 协同完成侦察、漏洞利用与结果验证，输出可复现 PoC、修复建议与报告；支持 CLI 运行并接入 GitHub Actions / CI/CD。</li><li><strong>本周热度亮点</strong>：优化扫描启动并发、减少重型依赖导入、系统校正 Skills 文档，直接降低使用门槛，顺应自动化红队与 AI 安全评测升温。</li><li><strong>技术栈</strong>：Python，多 Agent 协同，CI/CD 集成，安全测试框架。</li></ul><h3 id="_5-santifer-career-ops" tabindex="-1">5. santifer/career-ops <a class="header-anchor" href="#_5-santifer-career-ops" aria-label="Permalink to &quot;5. santifer/career-ops&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/santifer/career-ops" target="_blank" rel="noreferrer">https://github.com/santifer/career-ops</a></li><li><strong>Star 数</strong>：约 68k（本周新增 ~3,800）</li><li><strong>项目简介</strong>：将通用编码 CLI 转换为求职 Agent 工作台，可扫描职位门户、生成结构化匹配评分、研究公司与联系人、定制 ATS 简历并跟踪申请管道；坚持 human-in-the-loop，不替用户自动提交。</li><li><strong>本周热度亮点</strong>：连续发布核心与 Web 版本，修复 PDF、批处理鉴权与多语言文档；完整具体的求职闭环比抽象 Agent 框架更易传播。</li><li><strong>技术栈</strong>：TypeScript / Python，Agent 工作流，human-in-the-loop。</li></ul><h3 id="_6-obra-superpowers" tabindex="-1">6. obra/superpowers <a class="header-anchor" href="#_6-obra-superpowers" aria-label="Permalink to &quot;6. obra/superpowers&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">https://github.com/obra/superpowers</a></li><li><strong>Star 数</strong>：约 277k（本周新增 ~3,700）</li><li><strong>项目简介</strong>：以一组 Skills 约束编码 Agent 的软件开发过程：先澄清需求与设计，再拆解计划，按红绿重构推进实现，通过子 Agent 分工与审查控制质量；兼容 Codex、Claude Code、Cursor、Gemini CLI、Devin 等。</li><li><strong>本周热度亮点</strong>：热度主要来自 v6.3.0 扩展多平台支持后的持续扩散，反映团队正在寻找跨模型通用的工程方法层。</li><li><strong>技术栈</strong>：Shell / Markdown（Skills 规范），多平台 Agent 兼容。</li></ul><h3 id="_7-volcengine-openviking" tabindex="-1">7. volcengine/OpenViking <a class="header-anchor" href="#_7-volcengine-openviking" aria-label="Permalink to &quot;7. volcengine/OpenViking&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/volcengine/OpenViking" target="_blank" rel="noreferrer">https://github.com/volcengine/OpenViking</a></li><li><strong>Star 数</strong>：约 32.5k（本周新增 ~3,400）</li><li><strong>项目简介</strong>：面向 Agent 的&quot;自进化&quot;上下文数据库，将资源、技能与长期记忆统一为 <code>viking://</code> 虚拟文件系统，用摘要/概览/详情三层结构加载；检索留可观察轨迹，会话后提炼用户偏好与 Agent 经验。</li><li><strong>本周热度亮点</strong>：v0.4.14~v0.4.16 连续发布，增加 TRAE CLI 记忆集成并调整 MCP、Skills 与 Studio，显示上下文工程正形成独立基础设施。</li><li><strong>技术栈</strong>：Python，虚拟文件系统，MCP，Agent Memory / RAG。</li></ul><h3 id="_8-mukul975-anthropic-cybersecurity-skills" tabindex="-1">8. mukul975/Anthropic-Cybersecurity-Skills <a class="header-anchor" href="#_8-mukul975-anthropic-cybersecurity-skills" aria-label="Permalink to &quot;8. mukul975/Anthropic-Cybersecurity-Skills&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/mukul975/Anthropic-Cybersecurity-Skills" target="_blank" rel="noreferrer">https://github.com/mukul975/Anthropic-Cybersecurity-Skills</a></li><li><strong>Star 数</strong>：约 30.8k（本周新增 ~2,800）</li><li><strong>项目简介</strong>：社区维护（非 Anthropic 官方）的网络安全 Skills 知识库，将数百项技能映射到 MITRE ATT&amp;CK、NIST CSF 2.0、MITRE ATLAS、D3FEND、NIST AI RMF 等框架，兼容 Codex、Claude Code、Cursor 等 20+ 平台。</li><li><strong>本周热度亮点</strong>：修订领域表与贡献规则，重建索引并增加质量/冲突检测 CI，使大规模安全知识从提示词集合走向可治理资产。</li><li><strong>技术栈</strong>：Python，Agent Skills 规范（agentskills.io），多安全框架映射。</li></ul><h3 id="_9-chaitanyagiri-munder-difflin" tabindex="-1">9. chaitanyagiri/munder-difflin <a class="header-anchor" href="#_9-chaitanyagiri-munder-difflin" aria-label="Permalink to &quot;9. chaitanyagiri/munder-difflin&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/chaitanyagiri/munder-difflin" target="_blank" rel="noreferrer">https://github.com/chaitanyagiri/munder-difflin</a></li><li><strong>Star 数</strong>：约 3.9k（本周新增 ~2,600）</li><li><strong>项目简介</strong>：本地多 Agent 桌面编排器，把 Codex、Claude Code、Gemini、Kimi、Qwen 等终端进程组织为可通信的&quot;办公室&quot;；Agent 通过 mailbox、共享黑板、事件日志与语义记忆协作，对费用/破坏性操作设人工门槛。</li><li><strong>本周热度亮点</strong>：v0.4.4~v0.4.5 发布；直接复用现有 CLI 统一管理多个本地 Agent 的场景非常具体，契合&quot;本地优先 + 多 Agent 协作&quot;趋势。</li><li><strong>技术栈</strong>：TypeScript，桌面应用，多 Agent 编排，语义记忆。</li></ul><h3 id="_10-semantica-agi-semantica" tabindex="-1">10. semantica-agi/semantica <a class="header-anchor" href="#_10-semantica-agi-semantica" aria-label="Permalink to &quot;10. semantica-agi/semantica&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/semantica-agi/semantica" target="_blank" rel="noreferrer">https://github.com/semantica-agi/semantica</a></li><li><strong>Star 数</strong>：约 10.5k（本周新增 ~2,300）</li><li><strong>项目简介</strong>：图原生（graph-native）AI 基础设施，将上下文、事实与决策建模为图，提供 W3C PROV-O 溯源、SHACL 约束、Datalog/SPARQL 推理、冲突检测与时间快照，帮助系统解释&quot;基于什么数据、为何得出结果&quot;。</li><li><strong>本周热度亮点</strong>：v0.6.6 发布后继续修复 RDF 导出与 IRI 规范化；可问责 AI 的差异化定位推动关注增长，面向金融/医疗/法律等受监管行业。</li><li><strong>技术栈</strong>：Python，知识图谱（RDF/SPARQL/SHACL），Datalog 推理，W3C PROV-O。</li></ul><h3 id="_11-cathrynlavery-diagram-design" tabindex="-1">11. cathrynlavery/diagram-design <a class="header-anchor" href="#_11-cathrynlavery-diagram-design" aria-label="Permalink to &quot;11. cathrynlavery/diagram-design&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/cathrynlavery/diagram-design" target="_blank" rel="noreferrer">https://github.com/cathrynlavery/diagram-design</a></li><li><strong>Star 数</strong>：约 25k（本周新增 ~8,500，图表类断层领先）</li><li><strong>项目简介</strong>：为 Claude Code / Codex / Pi 等 AI 助手提供的编辑级图表技能库，内置 38 种视觉图表类型，输出自包含 HTML + 内联 SVG，无阴影、无 Mermaid 套路，零构建零依赖。</li><li><strong>本周热度亮点</strong>：连续霸榜周趋势（多周新增 1.3w+），本周再增 ~8,500；AI 生成内容从&quot;正确&quot;走向&quot;好看&quot;，可视化表达质量成为 AI 输出核心评判维度。</li><li><strong>技术栈</strong>：HTML / SVG，Agent Skills 规范，无 JS 静态输出。</li></ul><h3 id="_12-tencentcloud-tencentdb-agent-memory" tabindex="-1">12. TencentCloud/TencentDB-Agent-Memory <a class="header-anchor" href="#_12-tencentcloud-tencentdb-agent-memory" aria-label="Permalink to &quot;12. TencentCloud/TencentDB-Agent-Memory&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/TencentCloud/TencentDB-Agent-Memory" target="_blank" rel="noreferrer">https://github.com/TencentCloud/TencentDB-Agent-Memory</a></li><li><strong>Star 数</strong>：约 22.6k（本周新增 ~3,900，蝉联记忆类热点）</li><li><strong>项目简介</strong>：面向长周期、多步 Agent 的分层记忆系统，结合基于 Mermaid 的符号短期记忆与分层长期表示，降低上下文/Token 成本，保留可追溯性与按需下钻能力。</li><li><strong>本周热度亮点</strong>：作为&quot;Agent 团队记忆中枢&quot;持续蝉联热榜；与 OpenViking、macro、code-graph-rag 共同构成本周&quot;上下文工程&quot;新基建主线。</li><li><strong>技术栈</strong>：TypeScript，分层记忆架构，RAG，符号化短期记忆（Mermaid）。</li></ul><h2 id="本周趋势总结" tabindex="-1">本周趋势总结 <a class="header-anchor" href="#本周趋势总结" aria-label="Permalink to &quot;本周趋势总结&quot;">​</a></h2><ol><li><strong>Skills 成为工程产品</strong>：mattpocock/skills、obra/superpowers、Anthropic-Cybersecurity-Skills 等多项目上榜，Skills 已具备版本、安装、测试与治理机制。</li><li><strong>上下文工程 = Agent 新基建</strong>：OpenViking、TencentDB-Agent-Memory、semantica、code-graph-rag 四条线索均围绕&quot;记忆与上下文&quot;，继 RAG 之后成为新共识方向。</li><li><strong>本地优先 + 多 Agent 协作</strong>：munder-difflin、OpenClaw 生态、omlx（Apple Silicon 推理）反映端侧与本地编排升温。</li><li><strong>AI 安全与内容生成并行</strong>：strix（AI 渗透测试）、MoneyPrinterTurbo（AI 短视频）体现 AI 应用从工具层向垂直落地加速。</li></ol><blockquote><p>注：以上 Star 数与周增量为多源公开快照重建近似值，仅供参考，非官方精确计数。</p></blockquote>',31)])])}const p=r(o,[["render",a]]);export{d as __pageData,p as default};
